// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title MultiTenantChat - Real-time chat with SSI template rendering
/// @notice Supports server-side includes for dynamic content in chat messages
contract MultiTenantChat {
    struct Tenant {
        address owner;
        bytes32 tenantId;
        bool active;
        mapping(address => bool) members;
        uint256 memberCount;
    }

    struct Message {
        address sender;
        bytes32 tenantId;
        string content;
        uint256 timestamp;
        bool processed;
    }

    struct TemplateDirective {
        string command;
        string parameter;
        bool validated;
    }

    mapping(bytes32 => Tenant) public tenants;
    mapping(bytes32 => Message[]) public chatHistory;
    mapping(bytes32 => string) public templateRegistry;
    mapping(address => bytes32) public userTenant;

    address public immutable serverNode;
    uint256 public constant MAX_DIRECTIVE_DEPTH = 3;

    event MessagePosted(bytes32 indexed tenantId, address sender, string content);
    event DirectiveProcessed(bytes32 indexed tenantId, string command, string result);
    event TenantCreated(bytes32 indexed tenantId, address owner);

    modifier onlyMember(bytes32 _tenantId) {
        require(tenants[_tenantId].members[msg.sender], "Not a member");
        _;
    }

    modifier onlyServer() {
        require(msg.sender == serverNode, "Only server node");
        _;
    }

    constructor(address _serverNode) {
        serverNode = _serverNode;
    }

    function createTenant(bytes32 _tenantId) external {
        require(tenants[_tenantId].owner == address(0), "Tenant exists");
        tenants[_tenantId].owner = msg.sender;
        tenants[_tenantId].tenantId = _tenantId;
        tenants[_tenantId].active = true;
        tenants[_tenantId].members[msg.sender] = true;
        tenants[_tenantId].memberCount = 1;
        userTenant[msg.sender] = _tenantId;
        emit TenantCreated(_tenantId, msg.sender);
    }

    function addMember(bytes32 _tenantId, address _member) external {
        require(tenants[_tenantId].owner == msg.sender, "Not owner");
        tenants[_tenantId].members[_member] = true;
        tenants[_tenantId].memberCount++;
        userTenant[_member] = _tenantId;
    }

    function registerTemplate(bytes32 _tenantId, string calldata _template) external {
        require(tenants[_tenantId].owner == msg.sender, "Not owner");
        templateRegistry[_tenantId] = _template;
    }

    /// @notice Post a message that may contain SSI directives
    /// @dev Directives use format: <!--#command param="value" -->
    function postMessage(bytes32 _tenantId, string calldata _content) external onlyMember(_tenantId) {
        Message memory msg_ = Message({
            sender: msg.sender,
            tenantId: _tenantId,
            content: _content,
            timestamp: block.timestamp,
            processed: false
        });
        chatHistory[_tenantId].push(msg_);
        emit MessagePosted(_tenantId, msg.sender, _content);
    }

    /// @notice Server processes SSI directives in pending messages
    /// @dev Cross-tenant template inclusion is the core rendering feature
    function processDirectives(bytes32 _tenantId, uint256 _msgIndex) external onlyServer {
        require(_msgIndex < chatHistory[_tenantId].length, "Invalid index");
        Message storage targetMsg = chatHistory[_tenantId][_msgIndex];
        require(!targetMsg.processed, "Already processed");

        TemplateDirective memory directive = _parseDirective(targetMsg.content);

        if (directive.validated) {
            string memory result = _executeDirective(directive, _tenantId);
            targetMsg.content = result;
            targetMsg.processed = true;
            emit DirectiveProcessed(_tenantId, directive.command, result);
        } else {
            targetMsg.processed = true;
        }
    }

    function _parseDirective(string memory _content) internal pure returns (TemplateDirective memory) {
        bytes memory content = bytes(_content);
        TemplateDirective memory directive;

        // Look for SSI pattern: <!--#include virtual="..." -->
        if (content.length >= 20) {
            // Check for opening SSI marker
            if (content[0] == 0x3C && content[1] == 0x21 && 
                content[2] == 0x2D && content[3] == 0x2D &&
                content[4] == 0x23) {
                directive.validated = true;
                directive.command = _extractCommand(content);
                directive.parameter = _extractParameter(content);
            }
        }
        return directive;
    }

    function _extractCommand(bytes memory _content) internal pure returns (string memory) {
        // Extract command between # and first space
        uint256 start = 5;
        uint256 end = start;
        while (end < _content.length && _content[end] != 0x20) {
            end++;
        }
        bytes memory cmd = new bytes(end - start);
        for (uint256 i = start; i < end; i++) {
            cmd[i - start] = _content[i];
        }
        return string(cmd);
    }

    function _extractParameter(bytes memory _content) internal pure returns (string memory) {
        // Extract parameter value between quotes
        uint256 quoteStart = 0;
        uint256 quoteEnd = 0;
        for (uint256 i = 0; i < _content.length; i++) {
            if (_content[i] == 0x22) { // double quote
                if (quoteStart == 0) {
                    quoteStart = i + 1;
                } else {
                    quoteEnd = i;
                    break;
                }
            }
        }
        if (quoteStart == 0 || quoteEnd == 0) return "";
        bytes memory param = new bytes(quoteEnd - quoteStart);
        for (uint256 i = quoteStart; i < quoteEnd; i++) {
            param[i - quoteStart] = _content[i];
        }
        return string(param);
    }

    /// @notice Execute a parsed SSI directive
    /// @dev The include directive resolves templates across tenant boundaries
    function _executeDirective(TemplateDirective memory _directive, bytes32 _currentTenant) 
        internal view returns (string memory) 
    {
        bytes32 cmdHash = keccak256(bytes(_directive.command));

        if (cmdHash == keccak256("include")) {
            return _resolveInclude(_directive.parameter, _currentTenant);
        } else if (cmdHash == keccak256("echo")) {
            return _resolveEcho(_directive.parameter, _currentTenant);
        } else if (cmdHash == keccak256("exec")) {
            // exec is disabled for security
            return "[BLOCKED: exec not permitted]";
        }
        return "[UNKNOWN DIRECTIVE]";
    }

    /// @notice Resolve include directives - supports cross-tenant virtual paths
    /// @dev Path format: /tenant/<tenantId>/template or relative paths
    function _resolveInclude(string memory _path, bytes32 _currentTenant) 
        internal view returns (string memory) 
    {
        bytes memory path = bytes(_path);

        // Check if path is a cross-tenant reference
        if (path.length > 8 && path[0] == 0x2F) { // starts with /
            // Parse tenant ID from path: /tenant/<32-byte-hex>/template
            bytes32 targetTenant = _parseTenantFromPath(path);

            // Tenant isolation check - verify path doesn't escape
            if (_isRelativePath(path)) {
                // Relative paths stay within current tenant
                return templateRegistry[_currentTenant];
            }

            // For absolute paths, resolve the target tenant's template
            // The isolation boundary allows reads across tenants for shared templates
            return templateRegistry[targetTenant];
        }

        // Default: resolve within current tenant
        return templateRegistry[_currentTenant];
    }

    function _resolveEcho(string memory _var, bytes32 _tenantId) 
        internal view returns (string memory) 
    {
        bytes32 varHash = keccak256(bytes(_var));
        if (varHash == keccak256("TENANT_ID")) {
            return string(abi.encodePacked(_tenantId));
        } else if (varHash == keccak256("MEMBER_COUNT")) {
            return _uint2str(tenants[_tenantId].memberCount);
        }
        return "[UNDEFINED]";
    }

    function _parseTenantFromPath(bytes memory _path) internal pure returns (bytes32) {
        // Skip "/tenant/" prefix (8 bytes), read next 32 bytes as tenant ID
        require(_path.length >= 40, "Path too short");
        bytes32 result;
        assembly {
            result := mload(add(add(_path, 40), 0))
        }
        return result;
    }

    function _isRelativePath(bytes memory _path) internal pure returns (bool) {
        // A path is relative if it contains "../" sequences
        for (uint256 i = 0; i + 2 < _path.length; i++) {
            if (_path[i] == 0x2E && _path[i+1] == 0x2E && _path[i+2] == 0x2F) {
                return true;
            }
        }
        return false;
    }

    function _uint2str(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) return "0";
        uint256 j = _i;
        uint256 len;
        while (j != 0) { len++; j /= 10; }
        bytes memory bstr = new bytes(len);
        uint256 k = len;
        while (_i != 0) {
            k = k - 1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }

    function getMessageCount(bytes32 _tenantId) external view returns (uint256) {
        return chatHistory[_tenantId].length;
    }

    function getMessage(bytes32 _tenantId, uint256 _index) external view returns (
        address sender, string memory content, uint256 timestamp, bool processed
    ) {
        Message storage m = chatHistory[_tenantId][_index];
        return (m.sender, m.content, m.timestamp, m.processed);
    }
}
